import{sources}from './evidence.js';import{updateIllustration,getIllustrationSettings}from './illustrations.js';
const $=id=>document.getElementById(id);const params=new URLSearchParams(location.search);const pick=(key,values,fallback)=>values.includes(params.get(key))?params.get(key):fallback;let lens=pick('lens',['multi','enhanced','edof'],'multi'),topic=pick('topic',['lens','astigmatism'],'lens'),situation=pick('scene',['night','arm','reading','everyday'],'night'),view=pick('view',['a','both','b'],'both'),feature=null,step=0,answers=[];
const data={
mono:{night:['Fewer halo-related optical effects','Compared with Multifocal, generally fewer halos and less contrast loss; this does not guarantee no halos. ','benefit','guideline'],reading:['Reading glasses usually needed','Assuming both eyes target distance. ','cost','rcophth']},
multi:{title:'Multifocal',subtitle:'Multiple foci · Includes Trifocal',night:['More halo and contrast trade-offs','May make night driving harder; the impact varies by model and person. ','cost','patient'],reading:['Less reliance on reading glasses','Glasses may still be needed for some activities. ','benefit','patient']},
enhanced:{title:'Enhanced monofocal',subtitle:'One main focus · Some added intermediate range',night:['Depends on the exact model','A short-term trial found no significant differences in the contrast and halo/glare measures tested; that does not establish equivalence. ','neutral','enhanced'],reading:['Reading glasses usually still needed','The extra benefit is mainly intermediate vision; near reading usually still needs glasses. ','cost','patient']},
edof:{title:'EDOF',subtitle:'EDOF',night:['Trade-offs depend on the design','Ask about dim-light contrast and halos with the proposed model. ','neutral','guideline'],reading:['Near glasses usually still needed','Primarily extends useful vision into intermediate distances. ','cost','guideline']}}
data.mono.intermediate=['Intermediate glasses may be needed','When both eyes target distance, arm’s-length detail may be less clear. ','cost','patient'];
data.multi.intermediate=['May reduce intermediate glasses use','Trifocal includes an intermediate focus; results vary by model and eye health. ','benefit','guideline'];
data.enhanced.intermediate=['Some added intermediate range','Some studied models improved intermediate vision; the exact model matters. ','benefit','enhanced'];
data.edof.intermediate=['Mainly extends intermediate vision','Intermediate vision is a principal aim of EDOF. ','benefit','guideline'];
const contexts={arm:['Arm’s length: the guava in your hand','Target approximately 80 cm; start without glasses, then pull the glasses down to compare. '],night:['Clearer nights or less reliance on glasses?','Both aim to improve vision, with different trade-offs. '],reading:['Comfortable with reading glasses, or hoping to use them less?','Consider night-vision trade-offs too. '],everyday:['Daytime detail and contrast','This compares a distant street; choose Reading a book for near vision. ']};
function cell(id,entry){const [title,body,kind,source]=entry;const e=$(id);e.classList.remove('benefit','cost','neutral');e.classList.add(kind);e.replaceChildren();const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=body+' ';const a=document.createElement('a');a.textContent='Source ↗';a.href=sources[source];a.target='_blank';a.rel='noopener';p.append(a);e.append(h,p);}
function render(){updateIllustration({lens,situation,view,topic});const first=situation==='reading'?'reading':situation==='arm'?'intermediate':'night',second=first==='night'?'reading':'night';$('situation').value=situation;$('comparison').dataset.view=view;$('context').dataset.scene=situation;$('scene-title').textContent=contexts[situation][0];$('scene-description').textContent=contexts[situation][1];$('image-note').hidden=situation!=='night';$('b-title').textContent=data[lens].title;$('b-subtitle').textContent=data[lens].subtitle;for(const[n,k]of [['one',first],['two',second]]){$('row-'+n).textContent=(n==='one'?'01':'02')+' · '+(k==='night'?'Night vision':k==='intermediate'?'Arm’s length without glasses':'Reading without glasses');cell('a-'+n,k==='night'&&lens!=='multi'?['Standard monofocal optics','A reference for assessing the extra viewing range and optical effects of B. ','neutral','patient']:data.mono[k]);cell('b-'+n,data[lens][k]);}$('takeaway').textContent=lens==='multi'?'The main trade-off: less reliance on glasses may come with more halos and other optical effects. ':lens==='enhanced'?'Key question: how much useful intermediate vision does this exact model add?':'Key question: is the extra intermediate range worth this model’s optical trade-offs?';document.querySelectorAll('[data-view]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.view===view)));document.querySelectorAll('[data-lens]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.lens===lens)));}
const featureText={toric:'<p><strong>Toric builds astigmatism correction into the IOL. </strong>When regular corneal astigmatism needs correction, Toric can reduce reliance on cylinder glasses. A non-toric IOL with appropriate glasses is another way to correct it. </p><p><strong>Consider:</strong>Toric needs accurate axis alignment. Rotation can leave residual astigmatism and sometimes requires surgical repositioning. This does not remove the underlying monofocal-versus-multifocal trade-offs. </p><p>Ask the surgeon whether it is worthwhile based on your examination results. <a href="'+sources.guideline+'" target="_blank" rel="noopener">ESCRS recommendations ↗</a> · <a href="'+sources.toric+'" target="_blank" rel="noopener">Rotation and repositioning study ↗</a></p>',aspheric:'<p><strong>Aspheric: the surface is not part of a sphere. </strong>Designs handle spherical aberration differently; some compensate for corneal spherical aberration. </p><p><strong>Consider:</strong>Benefits depend on eye characteristics and IOL design. Some aberration-correcting designs are more sensitive to tilt or decentration. It is often a built-in design feature, not necessarily a separate add-on. </p><p>The term Aspheric alone does not tell you the reading range. <a href="'+sources.aspheric+'" target="_blank" rel="noopener">Optical explanation ↗</a></p>'};
function showFeature(which){feature=feature===which?null:which;for(const k of ['toric','aspheric']){$(k+'-open').setAttribute('aria-expanded',String(feature===k));$(k+'-open').querySelector('span').textContent=feature===k?'−':'＋';}$('feature-note').hidden=!feature;$('feature-note').innerHTML=feature?featureText[feature]:'';}
$('situation').onchange=()=>{situation=$('situation').value;render();};document.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>{view=e.dataset.view;render();});document.querySelectorAll('[data-lens]').forEach(e=>e.onclick=()=>{lens=e.dataset.lens;render();$('options').close();});$('alternatives').onclick=()=>$('options').showModal();$('sources-open').onclick=()=>$('sources').showModal();for(const k of ['toric','aspheric'])$(k+'-open').onclick=()=>showFeature(k);document.querySelectorAll('[data-close]').forEach(e=>e.onclick=()=>e.closest('dialog').close());
const sourceNames={guideline:'ESCRS cataract surgery recommendations',patient:'ESCRS patient information',rcophth:'Royal College of Ophthalmologists / RNIB patient guide (2025)',enhanced:'Enhanced-monofocal randomized trial (2025)',toric:'Toric rotation and repositioning study (2023)',aspheric:'ESCRS spherical aberration explanation'};for(const[k,v]of Object.entries(sourceNames)){const a=document.createElement('a');a.textContent=v+' ↗';a.href=sources[k];a.target='_blank';a.rel='noopener';$('source-list').append(a);}const trial=document.createElement('p');trial.textContent='Enhanced-lens trial: 172 patients; Eyhance Optiblue, Impress and NSP-3 compared with Tecnis monofocal Optiblue, with two months of follow-up. This does not establish equivalence, long-term safety, or the same performance for every enhanced model. ';$('source-list').append(trial);
const qs=[['Which matters more to you?',[['contrast','Comfortable nights and clear contrast'],['freedom','Less reliance on glasses']]],['Are reading glasses acceptable?',[['yes','Yes, I am used to glasses'],['no','I would prefer to use them less']]],['Has your corneal astigmatism been measured?',[['yes','Yes; I can ask the surgeon about the result'],['unknown','Not yet / Not sure']]]];
function decision(){const done=step===3;$('step-label').textContent=done?'Questions to take to your surgeon':'Your priorities · '+(step+1)+' / 3';$('back').hidden=step===0;$('answers').replaceChildren();if(!done){$('question').textContent=qs[step][0];$('decision-note').textContent=step===2?'Suitability for Toric requires examination measurements. ':'No lens has every advantage. Start with what matters most to you. ';for(const[v,t]of qs[step][1]){const b=document.createElement('button');b.textContent=t;b.onclick=()=>{answers[step]=v;step++;decision();};$('answers').append(b);}}else{const mono=answers[0]==='contrast'&&answers[1]==='yes';$('question').textContent=mono?'“Would distance-targeted Monofocal suit my priorities?”':answers[0]==='contrast'?'“Can I gain intermediate range while preserving comfortable night vision?”':'“How much less reliance on glasses would make these optical trade-offs worthwhile for me?”';$('decision-note').textContent='This is a consultation prompt, not a prescription for an implant. '+(answers[2]==='unknown'?'Ask for your corneal astigmatism measurements. ':'Ask whether the measured astigmatism warrants Toric correction. ');const b=document.createElement('button');b.textContent='Back to comparison';b.onclick=()=>{$('decision').close();};const r=document.createElement('button');r.textContent='Start again';r.onclick=()=>{step=0;answers=[];decision();};$('answers').append(b,r);}}
$('help').onclick=()=>{decision();$('decision').showModal();};$('back').onclick=()=>{step=Math.max(0,step-1);answers=answers.slice(0,step);decision();};document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||/SELECT|INPUT|TEXTAREA/.test(e.target.tagName))return;if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();changeScene(e.key==='ArrowLeft'?-1:1);}});
if(document.modelContext?.registerTool){const ac=new AbortController();window.addEventListener('pagehide',()=>ac.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'compare_lens_choices',description:'Show source-linked lens trade-offs. Changes only the educational comparison; does not recommend an implant.',inputSchema:{type:'object',properties:{situation:{type:'string',enum:['night','arm','reading','everyday']},lens:{type:'string',enum:['multi','enhanced','edof']},view:{type:'string',enum:['a','both','b']}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Expected comparison options');const allowed={situation:['night','arm','reading','everyday'],lens:['multi','enhanced','edof'],view:['a','both','b']};for(const[k,v]of Object.entries(input))if(!allowed[k]?.includes(v))throw Error('Invalid '+k);situation=input.situation||situation;lens=input.lens||lens;view=input.view||view;render();return{lensA:'distance-targeted monofocal',lensB:lens,situation,view,scope:'General evidence; not a patient-specific prediction'};}},{signal:ac.signal})).catch(()=>{});}catch{}}
render();

function showPanel(panel){
  const illustration=panel==='illustration';
  $('comparison').dataset.panel=panel;
  $('illustration-panel').hidden=!illustration;
  $('details-panel').hidden=illustration;
  for(const p of ['illustration','details']){const t=$(p+'-tab');t.setAttribute('aria-selected',String(p===panel));t.tabIndex=p===panel?0:-1;}
}
for(const p of ['illustration','details']){
  $(p+'-tab').onclick=()=>showPanel(p);
  $(p+'-tab').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();e.stopPropagation();const next=e.key==='Home'?'illustration':e.key==='End'?'details':p==='illustration'?'details':'illustration';showPanel(next);$(next+'-tab').focus();}};
}
$('return-illustration').onclick=()=>{showPanel('illustration');$('illustration-tab').focus();};

function changeScene(direction){const scenes=['night','arm','reading','everyday'];situation=scenes[(scenes.indexOf(situation)+direction+scenes.length)%scenes.length];render();}
$('scene-prev').onclick=()=>changeScene(-1);
$('scene-next').onclick=()=>changeScene(1);
let swipeStart=null;
$('comparison').addEventListener('touchstart',e=>{
  swipeStart=null;
  if(document.querySelector('dialog[open]')||e.touches.length!==1||e.target.closest('input,select,button,a,[role="tab"]'))return;
  swipeStart={x:e.touches[0].clientX,y:e.touches[0].clientY};
},{passive:true});
$('comparison').addEventListener('touchend',e=>{
  if(!swipeStart)return;
  const t=e.changedTouches[0],dx=t.clientX-swipeStart.x,dy=t.clientY-swipeStart.y;swipeStart=null;
  if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.7)changeScene(dx<0?1:-1);
},{passive:true});
$('comparison').addEventListener('touchcancel',()=>{swipeStart=null;},{passive:true});

document.querySelectorAll('[data-topic]').forEach(button=>button.onclick=()=>{topic=button.dataset.topic;document.querySelectorAll('[data-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.topic===topic)));render();});

const languageLink=document.querySelector('.language-switch');languageLink.addEventListener('click',()=>{const target=new URL(languageLink.href);target.search=new URLSearchParams({scene:situation,lens,topic,view,panel:$('comparison').dataset.panel,...getIllustrationSettings()}).toString();languageLink.href=target.href;});
document.querySelectorAll('[data-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.topic===topic)));

showPanel(pick('panel',['illustration','details'],'illustration'));
